css:
.pricing {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 16px;
  align-items: stretch;
  padding: 16px;
}

.tier {
  display: flex;
  flex-direction: column;
  padding: 20px;
  background: #fafafa;
  border: 1px solid #d4d4d8;
  border-radius: 8px;
}

.name,
.price {
  margin: 0;
}

.name {
  font-weight: 600;
}

.price {
  margin-top: 8px;
  font-size: 24px;
  font-weight: 700;
}

.features {
  flex: 1; /* grows so the bottoms line up */
  margin: 16px 0 0;
  padding-left: 18px;
}

.featured {
  background: #18181b;
  color: #fafafa;
}

@media (min-width: 720px) {
  .featured {
    position: relative;
    z-index: 1;
    margin-top: -12px;
  }
}
